def unpack_from(fmt, data, off):
    return struct.unpack_from(fmt, data, off)


def parse_elf(data: bytes) -> ELF:
    if len(data) < 16:
        raise ParseError("file is smaller than ELF header's e_ident")
    if data[:4] != b"\\x7fELF":
        raise ParseError("mismatched magic: not an ELF file")
    cls = data[4]
    if cls == 1:
        is64 = False
        header_size = 52
    elif cls == 2:
        is64 = True
        header_size = 64
    else:
        raise ParseError(f"Unknown bitness: {{cls}}")
    enc = data[5]
    if enc == 1:
        endian = '<'
    elif enc == 2:
        endian = '>'
    else:
        raise ParseError(f"Unknown endianness: {{enc}}")
    if len(data) < header_size:
        raise ParseError("file is smaller than ELF file header")

    if is64:
        vals = unpack_from(endian + 'HHIQQQIHHHHHH', data, 16)
        keys = ['e_type','e_machine','e_version','e_entry','e_phoff','e_shoff','e_flags','e_ehsize','e_phentsize','e_phnum','e_shentsize','e_shnum','e_shstrndx']
    else:
        vals = unpack_from(endian + 'HHIIIIIHHHHHH', data, 16)
        keys = ['e_type','e_machine','e_version','e_entry','e_phoff','e_shoff','e_flags','e_ehsize','e_phentsize','e_phnum','e_shentsize','e_shnum','e_shstrndx']
    hdr = dict(zip(keys, vals))

    phdrs = []
    ph_struct = 56 if is64 else 32
    for i in range(hdr['e_phnum']):
        off = hdr['e_phoff'] + i * hdr['e_phentsize']
        if off + ph_struct > len(data):
            # The original often panics on this; report a compact parse error instead.
            raise ParseError("file is smaller than program header table")
        if is64:
            p_type,p_flags,p_offset,p_vaddr,p_paddr,p_filesz,p_memsz,p_align = unpack_from(endian+'IIQQQQQQ', data, off)
        else:
            p_type,p_offset,p_vaddr,p_paddr,p_filesz,p_memsz,p_flags,p_align = unpack_from(endian+'IIIIIIII', data, off)
        phdrs.append(dict(index=i, off=off, p_type=p_type, p_flags=p_flags, p_offset=p_offset,
                          p_vaddr=p_vaddr, p_paddr=p_paddr, p_filesz=p_filesz,
                          p_memsz=p_memsz, p_align=p_align))

    shdrs = []
    sh_struct = 64 if is64 else 40
    for i in range(hdr['e_shnum']):
