        shdrs.append(dict(index=i, off=off, sh_name=sh_name, sh_type=sh_type, sh_flags=sh_flags,
                          sh_addr=sh_addr, sh_offset=sh_offset, sh_size=sh_size,
                          sh_link=sh_link, sh_info=sh_info, sh_addralign=sh_addralign,
                          sh_entsize=sh_entsize))

    shnames = ['' for _ in shdrs]
    idx = hdr.get('e_shstrndx', 0)
    if 0 <= idx < len(shdrs):
        tabhdr = shdrs[idx]
        start = tabhdr['sh_offset']; end = min(len(data), start + tabhdr['sh_size'])
