def human_unit(n):
    units = ['B','KiB','MiB','GiB','TiB']
    val = float(n); idx = 0
    while val >= 1024.0 and idx < len(units)-1:
        val /= 1024.0; idx += 1
    return f"{{val:.1f}} {{units[idx]}}"


def fmt_file_size(n):
    if n < 1024:
        return f"{{n}} B"
    return f"{{human_unit(n)}} ({{n}} B)"


def fmt_size_text(n):
    if n < 1024:
        return str(n)
    return f"{{n}} ({{human_unit(n)}})"


def span_addr(n):
    return f"<span class='number' title='{{n}}'>0x{{n:x}}</span>"


