def pflags_str(v):
    out = ''
    if v & 4: out += 'R'
    if v & 2: out += 'W'
    if v & 1: out += 'X'
    return out


def shflags_str(v):
    out = ''
    if v & 1: out += 'W'
    if v & 2: out += 'A'
    if v & 4: out += 'X'
