    rows=[]
    esc={{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}}
    for off in range(0,len(data),16):
        s=''
        for b in data[off:off+16]:
            if 32 <= b <= 126:
                ch=chr(b); s += esc.get(ch,ch)
            else:
                s += '.'
        rows.append(s)
    return '\n'.join(rows)


def offsets_pane(n):
    return '\n'.join(f"{{off:x}}" for off in range(0,n,16))


def add_ann(anns, start, end, cls, priority):
