    else:
        fields=[(16,18,'e_type'),(18,20,'e_machine'),(20,24,'e_version'),(24,28,'e_entry'),(28,32,'e_phoff'),(32,36,'e_shoff'),(36,40,'e_flags'),(40,42,'e_ehsize'),(42,44,'e_phentsize'),(44,46,'e_phnum'),(46,48,'e_shentsize'),(48,50,'e_shnum'),(50,52,'e_shstrndx')]
    for s,e,c in fields: add_ann(anns,s,e,c,50)
    # program headers and fields
    for ph in elf.phdrs:
        base=ph['off']; i=ph['index']
        size=56 if elf.is64 else 32
        add_ann(anns, base, base+size, f"bin_phdr{{i}} phdr", 30)
        if elf.is64:
            pf=[(0,4,'p_type'),(4,8,'p_flags'),(8,16,'p_offset'),(16,24,'p_vaddr'),(24,32,'p_paddr'),(32,40,'p_filesz'),(40,48,'p_memsz'),(48,56,'p_align')]
        else:
