def bytes_pane(elf):
    data=elf.data; anns=annotations(elf)
    starts={{}}; ends={{}}
    for a in anns:
        starts.setdefault(a.start,[]).append(a)
        ends.setdefault(a.end,[]).append(a)
    for k in starts:
        starts[k].sort(key=lambda a:(a.priority, -(a.end-a.start), a.order))
    for k in ends:
        ends[k].sort(key=lambda a:(-a.priority, (a.end-a.start), -a.order))
