def bytes_pane(elf):
    data=elf.data; anns=annotations(elf)
    starts={{}}; ends={{}}
    for a in anns:
        starts.setdefault(a.start,[]).append(a)
        ends.setdefault(a.end,[]).append(a)
    for k in starts:
        starts[k].sort(key=lambda a:(a.priority, -(a.end-a.start), a.order))
    for k in ends:
        ends[k].sort(key=lambda a:(-a.priority, (a.end-a.start), -a.order))
    out=[]
    def open_at(pos):
        for a in starts.get(pos,[]):
            out.append(f"<span class='{{a.cls}}'>")
    def close_at(pos):
        for a in ends.get(pos,[]):
            out.append("</span>")
    if data:
        open_at(0)
    for i in range(len(data)):
        out.append(byte_token(data,i))
        nxt=i+1
        close_at(nxt)
        if nxt < len(data):
            out.append('\n' if nxt % 16 == 0 else ' ')
            open_at(nxt)
    return ''.join(out)


def file_info_rows(path, elf):
    h=elf.hdr; ident=elf.data[:16]
    rows=[]
    rows.append(f"      <tr class='fileinfo_file_name'> <td>File name:</td> <td>{{path}}</td> </tr>\\n")
    rows.append(f"      <tr class='fileinfo_file_size'> <td>File size:</td> <td>{{fmt_file_size(len(elf.data))}}</td> </tr>\\n")
    rows.append(f"      <tr class='fileinfo_class'> <td>Object class:</td> <td>{{'64-bit' if elf.is64 else '32-bit'}}</td> </tr>\\n")
    rows.append(f"      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>{{data_encoding(elf)}}</td> </tr>\\n")
    abi=ident[7]; abiver=ident[8]
    if abi == 0:
        rows.append(f"      <tr class='fileinfo_abi'> <td>ABI:</td> <td>{{abi_str(abi)}}</td> </tr>\\n")
        if abiver != 0:
            rows.append(f"      <tr class='fileinfo_abi_ver'> <td>Uncommon ABI version(!):</td> <td>{{abiver}}</td> </tr>\\n")
    else:
        rows.append(f"      <tr class='fileinfo_abi'> <td>Uncommon ABI(!):</td> <td>{{abi_str(abi)}}</td> </tr>\\n")
        rows.append(f"      <tr class='fileinfo_abi_ver'> <td>ABI version:</td> <td>{{abiver}}</td> </tr>\\n")
    rows.append(f"      <tr class='fileinfo_e_type'> <td>Type:</td> <td>{{etype_str(h['e_type'])}}</td> </tr>\\n")
    rows.append(f"      <tr class='fileinfo_e_machine'> <td>Architecture:</td> <td>{{machine_str(h['e_machine'])}}</td> </tr>\\n")
    rows.append(f"      <tr class='fileinfo_e_entry'> <td>Entrypoint:</td> <td>{{span_addr(h['e_entry'])}}</td> </tr>\\n")
    rows.append(f"      <tr class='fileinfo_ph'> <td>Program headers:</td> <td><span title='0x{{h['e_phnum']:x}}' class='number fileinfo_e_phnum'>{{h['e_phnum']}}</span> * <span title='0x{{h['e_phentsize']:x}}' class='number fileinfo_e_phentsize'>{{h['e_phentsize']}}</span> @ <span title='0x{{h['e_phoff']:x}}' class='number fileinfo_e_phoff'>{{h['e_phoff']}}</span></td> </tr>\\n")
    rows.append(f"      <tr class='fileinfo_sh'> <td>Section headers:</td> <td><span title='0x{{h['e_shnum']:x}}' class='number fileinfo_e_shnum'>{{h['e_shnum']}}</span> * <span title='0x{{h['e_shentsize']:x}}' class='number fileinfo_e_shentsize'>{{h['e_shentsize']}}</span> @ <span title='0x{{h['e_shoff']:x}}' class='number fileinfo_e_shoff'>{{h['e_shoff']}}</span></td> </tr>\\n")
    return ''.join(rows)


def phdr_info_tables(elf):
    out=[]
