        out.append(f"            <tr> <td>Size in memory:</td> <td>{{span_size(ph['p_memsz'])}}</td> </tr>\\n")
        out.append(f"            <tr> <td>Alignment:</td> <td>{{span_align(ph['p_align'])}}</td> </tr>\\n")
        out.append("          </table>\\n")
