def shdr_info_tables(elf):
    out=[]
    for sh in elf.shdrs:
        i=sh['index']; name=elf.shnames[i] if i < len(elf.shnames) else ''
        out.append(f"          <table class='conceal itable' id='info_shdr{{i}}'>\\n")
        out.append("          <th colspan='2' class='shdr_itable'></th>\\n")
