        out.append(f"            <tr> <td>Flags:</td> <td>{{shflags_str(sh['sh_flags'])}}</td> </tr>\\n")
        out.append(f"            <tr> <td>Vaddr in memory:</td> <td>{{span_addr(sh['sh_addr'])}}</td> </tr>\\n")
