def strtab_strings(elf, sh):
    start=sh['sh_offset']; end=min(len(elf.data), start+sh['sh_size'])
    if not (0 <= start <= len(elf.data)): return []
    blob=elf.data[start:end]
    vals=[]
    for part in blob.split(b'\\0'):
        if not part: continue
        vals.append(part.decode('utf-8','replace'))
    return vals


def segment_section_info_tables(elf):
    out=[]
    for ph in elf.phdrs:
        i=ph['index']
        out.append(f"          <table class='conceal itable' id='info_segment{{i}}'>\\n")
        out.append("          <th colspan='2' class='segment_itable'></th>\\n")
        out.append(f"            <tr> <td>Type:</td> <td>{{ptype_str(ph['p_type'])}}</td> </tr>\\n")
        out.append(f"            <tr> <td>Size in file:</td> <td>{{span_size(ph['p_filesz'])}}</td> </tr>\\n")
        out.append(f"            <tr> <td>Size in memory:</td> <td>{{span_size(ph['p_memsz'])}}</td> </tr>\\n")
        out.append("          </table>\\n")
    for sh in elf.shdrs:
        i=sh['index']
        out.append(f"          <table class='conceal itable' id='info_section{{i}}'>\\n")
        out.append("          <th colspan='2' class='section_itable'></th>\\n")
        out.append(f"            <tr> <td>Type:</td> <td>{{shtype_str(sh['sh_type'])}}</td> </tr>\\n")
        out.append(f"            <tr> <td>Size:</td> <td>{{span_size(sh['sh_size'])}}</td> </tr>\\n")
        if sh['sh_type'] == 3:
            vals = strtab_strings(elf, sh)
            if vals:
                out.append("            <tr><td><br></td></tr>\\n")
                out.append("            <tr>\\n")
                out.append("              <td></td>\\n")
                out.append("              <td>\\n")
                out.append("                <div>\\n")
                for v in vals:
                    out.append(f"                  {{v}}\\n")
                out.append("                </div>\\n")
                out.append("              </td>\\n")
                out.append("            </tr>\\n")
        out.append("          </table>\\n")
    return ''.join(out)


def render_html(path, elf):
    title=os.path.basename(path)
    prefix=PREFIX_TEMPLATE.replace('<title>min64</title>', f'<title>{{title}}</title>')
    out=[]
    out.append(prefix)
    out.append(file_info_rows(path, elf))
    out.append("    </table>\\n")
    out.append(f"    <div id='offsets'>{{offsets_pane(len(elf.data))}}</div>\\n")
    out.append(f"    <div id='bytes'>{{bytes_pane(elf)}}</div>\\n")
    out.append(f"    <div id='ascii'>{{ascii_pane(elf.data)}}</div>\\n")
    out.append("    <table id='sticky_table' cellspacing='0'>\\n")
    out.append("      <tr>\\n")
    out.append("        <td id='desc'></td>\\n")
    out.append("        <td class='infotables'>\\n")
    out.append(phdr_info_tables(elf))
    out.append(shdr_info_tables(elf))
    out.append("        </td>\\n")
    out.append("        <td class='infotables'>\\n")
    out.append(segment_section_info_tables(elf))
    out.append("        </td>\\n")
    out.append("      </tr>\\n")
    out.append("    </table>\\n")
    out.append(SCRIPT_STATIC)
    out.append(FILELEN_TEMPLATE.replace('let fileLen = 64', f'let fileLen = {{len(elf.data)}}'))
    out.append(ARROWS_PREFIX)
    out.append("      connect('.e_phoff', '.bin_phdr0');\\n")
    out.append("      connect('.e_shoff', '.bin_shdr0');\\n")
    for ph in elf.phdrs:
        i=ph['index']; out.append(f"      connect('.bin_phdr{{i}} > .p_offset', '.bin_segment{{i}}');\\n")
    for sh in elf.shdrs:
        i=sh['index']; out.append(f"      connect('.bin_shdr{{i}} > .sh_offset', '.bin_section{{i}}');\\n")
        if sh['sh_link'] != 0:
            out.append(f"      connect('.bin_shdr{{i}} > .sh_link', '.bin_shdr{{sh['sh_link']}}');\\n")
    out.append("      pushArrowElems();\\n")
    out.append("    </script>\\n")
    out.append(SETTINGS_SCRIPT)
    return ''.join(out)


def main(argv):
    if len(argv) != 2:
        sys.stdout.write(USAGE + "\\n")
        return 1
    arg=argv[1]
    if arg in ('--help','-h'):
        sys.stdout.write(USAGE + "\\n")
        return 0
    if arg == '--version':
        sys.stdout.write(VERSION + "\\n")
        return 0
    try:
        with open(arg,'rb') as f:
            data=f.read()
    except OSError as e:
        sys.stderr.write(f"Failed to read file \\\"{{arg}}\\\": {{e.strerror}} (os error {{e.errno}})\\n")
        return 1
    try:
        elf=parse_elf(data)
        html=render_html(arg, elf)
    except ParseError as e:
        sys.stderr.write(f"Failed to parse ELF: {{e}}\\n")
        return 1
    outname=os.path.basename(arg)+'.html'
    try:
        with open(outname,'w',encoding='utf-8') as f:
            f.write(html)
    except OSError as e:
        sys.stderr.write(f"Failed to write report: {{e.strerror}} (os error {{e.errno}})\\n")
        return 1
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv))
