        desc=blob[off:off+descsz]
        off += ((descsz + 3)//4)*4
        name=name_bytes.rstrip(b'\0').decode('utf-8','replace')
        notes.append((name, ntype, desc))
        if namesz == 0 and descsz == 0:
            break
    return notes


def all_notes(elf):
    notes=[]
    for sh in elf.shdrs:
        if sh['sh_type'] != 7 or sh['sh_size'] == 0:
            continue
        start=sh['sh_offset']; end=min(len(elf.data), start+sh['sh_size'])
        if 0 <= start <= len(elf.data):
            notes.extend(parse_notes_from_blob(elf, elf.data[start:end]))
    if not notes:
        # Fallback for stripped/minimal objects with PT_NOTE but no section table.
        for ph in elf.phdrs:
            if ph['p_type'] == 4 and ph['p_filesz'] > 0:
                start=ph['p_offset']; end=min(len(elf.data), start+ph['p_filesz'])
                if 0 <= start <= len(elf.data):
                    notes.extend(parse_notes_from_blob(elf, elf.data[start:end]))
    return notes

